export const GetDistroAuditResponse = zod.object({
  scannedUnitCount: zod
    .number()
    .min(getDistroAuditResponseScannedUnitCountMin)
    .describe("Total number of units inspected"),
  flaggedUnitCount: zod.number().min(getDistroAuditResponseFlaggedUnitCountMin),
  invalidEntryCount: zod
    .number()
    .min(getDistroAuditResponseInvalidEntryCountMin)
    .describe("Total number of malformed entries across all flagged units"),
  units: zod.array(
    zod.object({
      unitId: zod.string(),
      unitName: zod.string(),
      echelon: zod.enum([
        "fireteam",
        "squad",
        "section",
        "platoon",
        "company",
        "battalion",
        "regiment",
        "battery",
        "team",
      ]),
      callsign: zod.string().nullable(),
      invalidEntries: zod.array(
        zod.object({
          bucket: zod
            .enum(["to", "cc", "bcc"])
            .describe(
              "Which distribution-list bucket the malformed value lives in",
            ),
          value: zod
            .string()
            .describe(
              "The literal stored value that failed the email shape regex",
            ),
        }),
      ),
      invalidCount: zod
        .number()
        .min(1)
        .describe(
          "Total number of malformed entries across all buckets for this unit",
        ),
    }),
  ),
  lastRun: zod
    .object({
      id: zod.string(),
      ranAt: zod.coerce.date(),
      auditedCount: zod
        .number()
        .min(getDistroAuditResponseLastRunOneAuditedCountMin)
        .describe("Number of units scanned during this run"),
      flaggedCount: zod
        .number()
        .min(getDistroAuditResponseLastRunOneFlaggedCountMin),
      invalidCount: zod
        .number()
        .min(getDistroAuditResponseLastRunOneInvalidCountMin),
      recipients: zod
        .array(zod.string())
        .describe("Recipient list the digest was (or would have been) sent to"),
      cc: zod.array(zod.string()),
      outcome: zod
        .enum([
          "sent",
          "skipped_no_flags",
          "skipped_no_recipients",
          "skipped_no_smtp",
          "failed",
        ])
        .describe(
          "`sent` — digest was delivered to SMTP. `skipped_no_flags` — audit found nothing to report so no email was sent. `skipped_no_recipients` — flagged units exist but `COMMS_HYGIENE_TO` is empty. `skipped_no_smtp` — SMTP not configured; digest preview was logged instead. `failed` — SMTP rejected the send (see `errorMessage`).",
        ),
      errorMessage: zod
        .string()
        .nullable()
        .describe("SMTP \/ runtime error message when `outcome` is `failed`"),
    })
    .nullable()
    .describe(
      "The most recent comms-hygiene digest run, regardless of outcome. `null` until the scheduler has run at least once. Use `outcome` to distinguish a successful send from a skipped\/failed attempt.",
    ),
  lastSuccessfulSend: zod
    .object({
      id: zod.string(),
      ranAt: zod.coerce.date(),
      auditedCount: zod
        .number()
        .min(getDistroAuditResponseLastSuccessfulSendOneAuditedCountMin)
        .describe("Number of units scanned during this run"),
      flaggedCount: zod
        .number()
        .min(getDistroAuditResponseLastSuccessfulSendOneFlaggedCountMin),
      invalidCount: zod
        .number()
        .min(getDistroAuditResponseLastSuccessfulSendOneInvalidCountMin),
      recipients: zod
        .array(zod.string())
        .describe("Recipient list the digest was (or would have been) sent to"),
      cc: zod.array(zod.string()),
      outcome: zod
        .enum([
          "sent",
          "skipped_no_flags",
          "skipped_no_recipients",
          "skipped_no_smtp",
          "failed",
        ])
        .describe(
          "`sent` — digest was delivered to SMTP. `skipped_no_flags` — audit found nothing to report so no email was sent. `skipped_no_recipients` — flagged units exist but `COMMS_HYGIENE_TO` is empty. `skipped_no_smtp` — SMTP not configured; digest preview was logged instead. `failed` — SMTP rejected the send (see `errorMessage`).",
        ),
      errorMessage: zod
        .string()
        .nullable()
        .describe("SMTP \/ runtime error message when `outcome` is `failed`"),
    })
    .nullable()
    .describe(
      "The most recent run whose outcome was `sent`, or `null` if no digest has ever been delivered. Surfaced separately so planners can see when the last digest actually went out even after a recent failure.",
    ),
});

/**
 * Re-uses the same `runCommsHygieneOnce` path as the scheduled job, so behavior matches exactly. The email is suppressed when no entries are flagged. Lets planners confirm a freshly cleaned roster will produce a clean digest, or push a digest ahead of a coordination meeting without waiting for the next scheduled run.
 * @summary Run the comms-hygiene audit and email the digest immediately
 */
export const sendDistroAuditDigestResponseAuditedMin = 0;

export const sendDistroAuditDigestResponseFlaggedMin = 0;

export const sendDistroAuditDigestResponseInvalidMin = 0;

export const SendDistroAuditDigestResponse = zod
  .object({
    audited: zod
      .number()
      .min(sendDistroAuditDigestResponseAuditedMin)
      .describe("Number of units inspected during the run"),
    flagged: zod
      .number()
      .min(sendDistroAuditDigestResponseFlaggedMin)
      .describe("Number of units with at least one malformed entry"),
    invalid: zod
      .number()
      .min(sendDistroAuditDigestResponseInvalidMin)
      .describe("Total number of malformed entries across all flagged units"),
    emailSent: zod
      .boolean()
      .describe("True when an email was actually dispatched to recipients"),
    reason: zod
      .enum(["no_flagged_entries", "no_recipients", "smtp_not_configured"])
      .optional()
      .describe(
        "When `emailSent` is false, why the email was not sent. `no_flagged_entries` means the digest was suppressed because every distro list is clean. `no_recipients` and `smtp_not_configured` indicate a server-side configuration gap.",
      ),
  })
  .describe("Outcome of an on-demand `runCommsHygieneOnce` invocation.");

/**
 * Returns the same subject / text / html that `sendDistroAuditDigest` would dispatch, without invoking the SMTP transport. Lets planners inspect the next email before it goes out — especially during pre-coordination windows where a false alarm would be embarrassing. `suppressed` is true when no entries are flagged (matching the live send's suppression behavior).
 * @summary Render the comms-hygiene digest without sending it
 */
export const previewDistroAuditDigestResponseAuditedMin = 0;

export const previewDistroAuditDigestResponseFlaggedMin = 0;

export const previewDistroAuditDigestResponseInvalidMin = 0;

export const PreviewDistroAuditDigestResponse = zod
  .object({
    audited: zod
      .number()
      .min(previewDistroAuditDigestResponseAuditedMin)
      .describe("Number of units inspected during the preview build"),
    flagged: zod
      .number()
      .min(previewDistroAuditDigestResponseFlaggedMin)
      .describe("Number of units with at least one malformed entry"),
    invalid: zod
      .number()
      .min(previewDistroAuditDigestResponseInvalidMin)
      .describe("Total number of malformed entries across all flagged units"),
    suppressed: zod
      .boolean()
      .describe(
        "True when no entries were flagged. The live send path suppresses the email in this case; the preview still returns the rendered payload so callers can confirm what would have been produced.",
      ),
    subject: zod
      .string()
      .describe("Email subject line that the live send would use"),
    text: zod
      .string()
      .describe("Plain-text email body that the live send would use"),
    html: zod.string().describe("HTML email body that the live send would use"),
  })
  .describe(
    "Rendered digest payload (subject \/ text \/ html) that the live send path would dispatch, returned without invoking SMTP.",
  );

/**
 * Returns the total number of `comms_hygiene_runs` rows on file, the oldest stored `ranAt`, the effective retention horizon (the dashboard override when set, otherwise `COMMS_HYGIENE_RETENTION_DAYS`, default 180), and the projected expiry of the oldest stored run. Lets the dashboard surface a small footnote like "247 runs on file · oldest expires Dec 12" so planners can see the prune policy is working and nothing important silently disappeared.
 * @summary Stored comms-hygiene run count and retention horizon
 */
export const getCommsHygieneStatsResponseTotalRunsMin = 0;

export const getCommsHygieneStatsResponseRetentionDaysMin = 0;

export const getCommsHygieneStatsResponseRetentionDaysOverrideMin = 0;

export const getCommsHygieneStatsResponseRetentionDaysDefaultMin = 0;

export const getCommsHygieneStatsResponseNearExpiryWindowDaysMin = 0;

export const getCommsHygieneStatsResponseNearExpiryCountMin = 0;

export const GetCommsHygieneStatsResponse = zod
  .object({
    totalRuns: zod
      .number()
      .min(getCommsHygieneStatsResponseTotalRunsMin)
      .describe("Total number of `comms_hygiene_runs` rows currently stored."),
    oldestRanAt: zod.coerce
      .date()
      .nullable()
      .describe(
        "Timestamp of the oldest stored run, or `null` when the table is empty.",
      ),
    retentionDays: zod
      .number()
      .min(getCommsHygieneStatsResponseRetentionDaysMin)
      .describe(
        "Effective retention horizon in days. Equal to `retentionDaysOverride` when an in-app override is active, otherwise `retentionDaysDefault`. 0 means retention is disabled.",
      ),
    retentionDaysOverride: zod
      .number()
      .min(getCommsHygieneStatsResponseRetentionDaysOverrideMin)
      .nullable()
      .describe(
        "Dashboard-set retention override in days, or `null` when no override is active and the env-var default applies. Surfaced so the footnote can flag when an admin has temporarily widened (or disabled) retention.",
      ),
    retentionDaysDefault: zod
      .number()
      .min(getCommsHygieneStatsResponseRetentionDaysDefaultMin)
      .describe(
        "Env-var (`COMMS_HYGIENE_RETENTION_DAYS`, default 180) used when no override is active. Returned alongside the effective value so the dashboard can label the source.",
      ),
    oldestExpiresAt: zod.coerce
      .date()
      .nullable()
      .describe(
        "When the oldest stored run is expected to age out of the table (oldest `ranAt` plus `retentionDays`). `null` when the table is empty or retention is disabled.",
      ),
    nearExpiryWindowDays: zod
      .number()
      .min(getCommsHygieneStatsResponseNearExpiryWindowDaysMin)
      .describe(
        'Configured \"expires soon\" window in days (`COMMS_HYGIENE_NEAR_EXPIRY_WINDOW_DAYS`, default 7). Rows whose projected expiry falls within this window of \"now\" are considered near-expiry. Always 0 when retention is disabled.',
      ),
    nearExpiryCount: zod
      .number()
      .min(getCommsHygieneStatsResponseNearExpiryCountMin)
      .describe(
        "Number of stored runs whose projected expiry (`ranAt` plus `retentionDays`) is within `nearExpiryWindowDays` of the current time, including any rows that have already passed their expiry but have not yet been pruned. Always 0 when retention is disabled.",
      ),
  })
  .describe(
    "Run-history stats for the dashboard footnote. Lets planners see how many digest runs are stored and when older ones will fall off under the active retention policy.",
  );

