/**
 * Published schedules are append-only audit records of pre-coordinated comms-denied pushes. There is intentionally no `PATCH` or `DELETE` on the schedule itself — to retract distribution, revoke or rotate the share token via `POST /schedules/{scheduleId}/share/revoke` / `.../share/rotate`; to publish revised events, call `POST /units/{unitId}/comms-denied/publish` again.
 * @summary Get a published schedule with its resupply events
 */
export const GetScheduleParams = zod.object({
  scheduleId: zod.coerce.string(),
});

export const getScheduleResponseUnitDistroEmailsItemRegExp = new RegExp(
  "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$",
);
export const getScheduleResponseUnitDistroCcEmailsItemRegExp = new RegExp(
  "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$",
);
export const getScheduleResponseUnitDistroBccEmailsItemRegExp = new RegExp(
  "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$",
);

export const GetScheduleResponse = zod.object({
  id: zod.string(),
  label: zod.string(),
  unitId: zod.string(),
  unitName: zod.string(),
  unitEchelon: zod.string().nullish(),
  unitLocation: zod.string().nullish(),
  unitClimate: zod.string().nullish(),
  unitOpTempo: zod.string().nullish(),
  unitAmmoPosture: zod.string().nullish(),
  unitDistroEmails: zod
    .array(
      zod.string().email().regex(getScheduleResponseUnitDistroEmailsItemRegExp),
    )
    .optional()
    .describe(
      "Distribution list of email addresses copied from the receiving unit at request time, used to pre-fill the schedule email recipients. Pre-existing malformed entries are still possible for older units and are filtered out client-side before opening the mailto draft.",
    ),
  unitDistroCcEmails: zod
    .array(
      zod
        .string()
        .email()
        .regex(getScheduleResponseUnitDistroCcEmailsItemRegExp),
    )
    .optional()
    .describe(
      "CC distribution list copied from the receiving unit at request time, used to pre-fill the cc= field of the schedule email. Pre-existing malformed entries are still possible for older units and are filtered out client-side before opening the mailto draft.",
    ),
  unitDistroBccEmails: zod
    .array(
      zod
        .string()
        .email()
        .regex(getScheduleResponseUnitDistroBccEmailsItemRegExp),
    )
    .optional()
    .describe(
      "BCC distribution list copied from the receiving unit at request time, used to pre-fill the bcc= field of the schedule email (silent recipients hidden from To\/CC). Pre-existing malformed entries are still possible for older units and are filtered out client-side before opening the mailto draft.",
    ),
  baselineId: zod.string().nullish(),
  horizonDays: zod.number(),
  burnModel: zod.string(),
  safetyMarginDays: zod.number(),
  resupplyLeadDays: zod.number(),
  publishedAt: zod.coerce.date().nullish(),
  shareToken: zod.string().nullish(),
  createdAt: zod.coerce.date().optional(),
  events: zod.array(
    zod.object({
      id: zod.string(),
      supplyClass: zod.string(),
      itemId: zod.string().nullish(),
      itemName: zod.string().nullish(),
      quantity: zod.number(),
      unit: zod.string(),
      scheduledFor: zod.coerce.date(),
      status: zod.string(),
      assignedTo: zod.string().nullish(),
      notes: zod.string().nullish(),
    }),
  ),
});

/**
 * Clears the schedule's share_token so the previously distributed
frontend deep link (`/s/{shareToken}`, served by the SPA, which
calls `GET /api/schedules/share/{shareToken}` under the hood)
immediately returns 404. Use this when a link has been over-shared
or leaked. To re-issue distribution, follow with
`POST /schedules/{scheduleId}/share/rotate` to mint a fresh token.

 * @summary Revoke (null out) the share token for a published schedule
 */
export const RevokeScheduleShareLinkParams = zod.object({
  scheduleId: zod.coerce.string(),
});

export const RevokeScheduleShareLinkResponse = zod.object({
  scheduleId: zod.string(),
  shareToken: zod
    .string()
    .nullable()
    .describe("Always null after a successful revoke."),
  revoked: zod.boolean(),
});

/**
 * Generates a new share_token for the schedule and returns it. Any
previously distributed `/s/{oldToken}` deep link (a SPA route, not
an API path — it resolves to `GET /api/schedules/share/{shareToken}`)
stops working immediately. Safe to call whether the link is
currently active or already revoked.

 * @summary Issue a fresh share token for a published schedule
 */
export const RotateScheduleShareLinkParams = zod.object({
  scheduleId: zod.coerce.string(),
});

export const RotateScheduleShareLinkResponse = zod.object({
  scheduleId: zod.string(),
  shareToken: zod
    .string()
    .describe(
      "The newly minted share token. Distribute this in place of the old one.",
    ),
});

